function getSourceDetailDefaultOwner(source) {
    if (source.sourceName.includes("Shopify") || source.sourceName.includes("Back-in-stock") || source.sourceName.includes("Ecommerce")) {
        return "Mina Cole";
    }
    if (source.sourceName.includes("WhatsApp")) {
        return "Tessa Nguyen";
    }
    if (source.sourceName.includes("Referral") || source.sourceName.includes("Campaign")) {
        return "Luis Park";
    }
    if (source.sourceName.includes("Event") || source.sourceName.includes("CSV")) {
        return "Operations";
    }
    return "Amara Shah";
}
